-- Additive production schema reconciliation for dashboard/runtime compatibility.
ALTER TYPE "PaymentStatus" ADD VALUE IF NOT EXISTS 'unpaid';
ALTER TYPE "OrderStatus" ADD VALUE IF NOT EXISTS 'shipped';
ALTER TYPE "ShipmentStatus" ADD VALUE IF NOT EXISTS 'shipped';
ALTER TABLE "Product" ADD COLUMN IF NOT EXISTS "weightKg" DOUBLE PRECISION;
ALTER TABLE "TenantSetting" ADD COLUMN IF NOT EXISTS "defaultProductWeightKg" DOUBLE PRECISION NOT NULL DEFAULT 0.5, ADD COLUMN IF NOT EXISTS "fallbackDeliveryFee" DECIMAL(65,30) NOT NULL DEFAULT 130;
ALTER TABLE "OrderShipment" ADD COLUMN IF NOT EXISTS "merchantReference" TEXT, ADD COLUMN IF NOT EXISTS "providerReference" TEXT, ADD COLUMN IF NOT EXISTS "providerStatus" TEXT, ADD COLUMN IF NOT EXISTS "customerDeliveryFee" DECIMAL(65,30), ADD COLUMN IF NOT EXISTS "courierCharge" DECIMAL(65,30), ADD COLUMN IF NOT EXISTS "codAmount" DECIMAL(65,30), ADD COLUMN IF NOT EXISTS "codFee" DECIMAL(65,30), ADD COLUMN IF NOT EXISTS "deliveryFeeVerified" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS "bookingState" TEXT NOT NULL DEFAULT 'pending', ADD COLUMN IF NOT EXISTS "bookingAttemptCount" INTEGER NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS "lastBookingError" TEXT, ADD COLUMN IF NOT EXISTS "lastBookingErrorCode" TEXT, ADD COLUMN IF NOT EXISTS "lastBookedAt" TIMESTAMP(3), ADD COLUMN IF NOT EXISTS "lastReconciledAt" TIMESTAMP(3), ADD COLUMN IF NOT EXISTS "nextReconcileAt" TIMESTAMP(3);
CREATE TABLE IF NOT EXISTS "CourierStoreMapping" ("id" TEXT NOT NULL, "provider" TEXT NOT NULL, "warehouseId" TEXT NOT NULL, "externalStoreId" TEXT NOT NULL, "externalStoreName" TEXT, "status" TEXT NOT NULL DEFAULT 'pending', "isActive" BOOLEAN NOT NULL DEFAULT true, "cityId" INTEGER, "zoneId" INTEGER, "areaId" INTEGER, "verifiedAt" TIMESTAMP(3), "lastError" TEXT, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "CourierStoreMapping_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX IF NOT EXISTS "CourierStoreMapping_provider_warehouseId_key" ON "CourierStoreMapping"("provider","warehouseId");
CREATE UNIQUE INDEX IF NOT EXISTS "CourierStoreMapping_provider_externalStoreId_key" ON "CourierStoreMapping"("provider","externalStoreId");
CREATE INDEX IF NOT EXISTS "CourierStoreMapping_provider_status_idx" ON "CourierStoreMapping"("provider","status");
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'CourierStoreMapping_warehouseId_fkey') THEN ALTER TABLE "CourierStoreMapping" ADD CONSTRAINT "CourierStoreMapping_warehouseId_fkey" FOREIGN KEY ("warehouseId") REFERENCES "Warehouse"("id") ON DELETE CASCADE ON UPDATE CASCADE; END IF; END $$;
